import java.util.regex.*;
import java.util.*;
import java.text.*;
import org.joda.time.*;
import org.joda.time.format.*;

public class T {
  public static void main(String[] args) throws Exception {
    String p = "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{11}$";
    String p2 = "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$";
    for (int i=0;i<20;i++) {
      String u = UUID.randomUUID().toString();
      System.out.println(u + " len_last=" + u.split("-")[4].length() + " p11=" + Pattern.matches(p,u) + " p12=" + Pattern.matches(p2,u));
    }
    // timestamp yyyyy
    SimpleDateFormat sdf = new SimpleDateFormat("yyyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
    try {
      Date d = sdf.parse("2024-08-05T13:47:00.000Z");
      System.out.println("parsed yyyyy: " + d + " " + d.getTime());
    } catch (Exception e) { System.out.println("yyyyy fail: " + e); }
    SimpleDateFormat sdf2 = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    sdf2.setTimeZone(TimeZone.getTimeZone("UTC"));
    Date d2 = sdf2.parse("2024-08-05T13:47:00.000Z");
    System.out.println("parsed yyyy: " + d2);

    // joda hh vs HH
    DateTimeFormatter f1 = DateTimeFormat.forPattern("yyyy-MM-dd'T'hh:mm:ss.SSS'Z'");
    DateTimeFormatter f2 = DateTimeFormat.forPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    DateTime dt = new DateTime(2024,8,5,13,47,0,0, DateTimeZone.UTC);
    System.out.println("hh: " + dt.toString(f1));
    System.out.println("HH: " + dt.toString(f2));

    // customer pattern
    String cp = "^[01-9a-zA-Z]+@[a-zA-Z]+[-][a-zA-Z]+";
    String[] customers = {"9999999999@onemoney-aa", "user@aa-handle", "9999999999@onemoney", "ab@cd-ef", "0test@ab-cd", "test_user@ab-cd"};
    for (String c: customers) System.out.println(c + " => " + Pattern.matches(cp, c));
  }
}
EOF
