import java.text.*;
import java.util.*;
public class T2 {
  public static void main(String[] args) throws Exception {
    String[] patterns = {"yyyyy-MM-dd'T'HH:mm:ss.SSS'Z'", "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"};
    String[] inputs = {
      "2024-08-05T13:47:00.000Z",
      "2024-08-05T13:47:00.00Z",
      "2024-08-05T13:47:00.0Z",
      "2024-08-05T13:47:00Z",
      "09999-08-05T13:47:00.000Z",
      "2020-01-01T00:00:00.000Z"
    };
    for (String p : patterns) {
      System.out.println("PATTERN " + p);
      SimpleDateFormat sdf = new SimpleDateFormat(p);
      sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
      sdf.setLenient(false);
      for (String in : inputs) {
        try {
          Date d = sdf.parse(in);
          System.out.println("  OK " + in + " -> " + d.getTime());
        } catch (Exception e) {
          System.out.println("  FAIL " + in + " : " + e.getMessage());
        }
      }
    }
    // Also check UUID with uppercase
    String p = "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$";
    String u = java.util.UUID.randomUUID().toString().toUpperCase();
    System.out.println("upper " + u + " " + java.util.regex.Pattern.matches(p, u));
    System.out.println("upper ci " + java.util.regex.Pattern.compile(p, java.util.regex.Pattern.CASE_INSENSITIVE).matcher(u).matches());
  }
}
